package com.example.clientdemopublicqa.core.config;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.util.Properties;

/**
 * Loads {@link Properties} files from the test classpath.
 *
 * Generated by qaff. Keep dependency-free so framework-core stays at the
 * bottom of the dependency direction.
 */
public final class ConfigLoader {

    private ConfigLoader() {
    }

    public static Properties fromClasspath(String classpathName) {
        Properties props = new Properties();
        ClassLoader cl = Thread.currentThread().getContextClassLoader();
        try (InputStream in = cl.getResourceAsStream(classpathName)) {
            if (in == null) {
                throw new IllegalStateException(
                        "Missing classpath resource: " + classpathName);
            }
            props.load(in);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return props;
    }
}
